def even_binomial_Coeff_Sum(n):
    sum_even = 0
    for k in range(0, n + 1, 2):
        # Calculate binomial coefficient C(n, k)
        binomial_coeff = 1
        if k > n - k:
            k = n - k  # Take advantage of symmetry to reduce computation
