def reverse_Array_Upto_K(input, k):
    # Check if k is out of bounds and adjust if necessary
    if k < 0 or k > len(input):
        return input.copy()

    # Slice the array up to k (inclusive) and reverse it
    reversed_slice = input[:k+1][::-1]

    # Combine the reversed slice with the rest of the array
    return reversed_slice + input[k+1:]
