def left_rotate(n, d):
    # Handle the case where d is 0 (rotate by 0 bits is the number itself)
    if d == 0:
        return n

    # Normalize the rotation amount to be within 0-31 (since it's a 32-bit number)
    d = d % 32

    # Perform the left rotation: (n << d) | (n >> (32 - d))
    return (n << d) | (n >> (32 - d))
```

