def left_rotate(n, d):
    n = n & 0xFFFFFFFF  # Ensure n is treated as a 32-bit unsigned integer
    d = d % 32          # Normalize d to be within 0-31
    return ((n << d) & 0xFFFFFFFF) | ((n >> (32 - d)) & 0xFFFFFFFF)
